import 'https://testingcf.jsdelivr.net/gh/MagicalAstrogy/MagVarUpdate/artifact/bundle.js';
import { registerMvuSchema } from 'https://testingcf.jsdelivr.net/gh/StageDog/tavern_resource/dist/util/mvu_zod.js';

// FF + MVU Core v1.5.8
// Full state is branch-local. Final MODEL_STATE is refreshed again at late prompt assembly.
(() => {
  const scriptWindow = window;
  const host = (() => {
    try { return window.parent && window.parent !== window ? window.parent : window; }
    catch (error) { return window; }
  })();

  // Tavern Helper scripts run inside srcdoc/iframe contexts. Helper APIs are often
  // injected into the script window, while visible UI/state lives on the parent.
  // Bridge both contexts instead of assuming the parent owns every API.
  const runtimeScopes = [...new Set([scriptWindow, host].filter(Boolean))];

  function runtimeFunction(name) {
    for (const scope of runtimeScopes) {
      if (typeof scope?.[name] === 'function') return scope[name].bind(scope);
    }
    return null;
  }

  function getSillyTavern() {
    for (const scope of runtimeScopes) {
      if (scope?.SillyTavern) return scope.SillyTavern;
    }
    return null;
  }

  function getTavernEvents() {
    for (const scope of runtimeScopes) {
      if (scope?.tavern_events) return scope.tavern_events;
    }
    return {};
  }

  const VERSION = 'FFMVU-1.5.8';
  const COMPATIBLE_SNAPSHOT_VERSIONS = new Set([VERSION, 'FFMVU-1.5.7', 'FFMVU-1.5.6', 'FFMVU-1.5.5', 'FFMVU-1.5.4', 'FFMVU-1.5.3', 'FFMVU-1.5.2', 'FFMVU-1.5.1']);
  const SNAPSHOT_META_KEY = 'ff_mvu_snapshot_meta';
  const LIVE_STATE_SENTINEL = '__FFMVU_LIVE_STATE__';
  const MODEL_STATE_RE = /<MODEL_STATE>[\s\S]*?<\/MODEL_STATE>/i;

  const clone = value => {
    if (typeof structuredClone === 'function') return structuredClone(value);
    return JSON.parse(JSON.stringify(value));
  };
  const isObject = value => value && typeof value === 'object' && !Array.isArray(value);
  const tupleValue = value => Array.isArray(value) ? value[0] : value;
  const asArray = value => Array.isArray(value) ? value : [];
  const asRecord = value => isObject(value) ? value : {};
  const unique = values => [...new Set(asArray(values).filter(value => typeof value === 'string' && value.trim()))];
  const text = value => value === null || value === undefined ? '' : String(value);
  const lower = value => text(value).trim().toLowerCase();
  const clamp = (value, min, max) => Math.max(min, Math.min(max, Number(value) || 0));

  const defaultState = {
    World_Calc: { Factions: {}, Locations: {}, Ruins: {}, Events: {} },
    World: {
      Date: ['Day 1', 'Date'],
      Time: ['08:00', 'Time'],
      Location: ['Unspecified', 'Location'],
      Weather: ['Clear', 'Weather'],
    },
    Mainchar: {
      Name: ['{{user}}', 'Name'], Image: ['', 'Portrait'], Race: ['Human', 'Race'], Age: ['18', 'Age'],
      Gender: ['Unspecified', 'Gender'], Occupation: ['Adventurer', 'Occupation'], Level: [1, 'Level'],
      Exp: [0, 'Experience'], 'Core-points': [0, 'Unassigned Points'], Mental_state: ['Calm', 'Mental State'],
      Strength: [5, 'Strength'], Agility: [5, 'Agility'], Constitution: [5, 'Constitution'],
      Intelligence: [5, 'Intelligence'], Wisdom: [5, 'Wisdom'], Charisma: [5, 'Charisma'],
      Hp_curr: [41, 'Current HP'], Hp_max: [41, 'Max HP'], Mp_curr: [28, 'Current MP'], Mp_max: [28, 'Max MP'],
      Sta_curr: [76, 'Current Stamina'], Sta_max: [76, 'Max Stamina'],
      Physical_attack: [12, 'Physical Attack'], Physical_defense: [5, 'Physical Defense'],
      Magic_attack: [12, 'Magic Attack'], Magic_defense: [5, 'Magic Defense'], Magic_assist: [10, 'Magic Support'],
      Quests: {}, Skills: {}, Equipment: {}, Inventory: {}, Talents: {},
      Outfit: { Initialized: false, Worn: {}, Wardrobe: {} },
      Real_estate: { Estates: {}, Buildings: {}, Assets: {} }, Buffs: {}, Ailments: {},
      Starting_weapon_request: ['', 'One-shot starting weapon preference'],
      Starting_weapon_status: ['none', 'none | pending | fulfilled'],
    },
    Familiar: {},
    Narrative: {
      Version: '1.0', Turn: 0, NextNpcId: 1,
      NPCs: {}, Relationships: {},
      GM_Notes: { Active: {}, Archive: {} },
      Chekhov: { Active: {}, Archive: {}, AuditEvery: 8, LastAuditTurn: 0 },
      WorldSim: { Threads: {}, Pressures: {}, Archive: {}, LastShift: '' },
      Scene: {
        Focus: '', LastBeat: '', OpenLoops: [], PresentNPCs: [], LocationKey: '',
        RelevantWorldKeys: [], Changed: true,
      },
    },
    MVUStatMenu_DB_Ver: VERSION,
    GameStarted: false,
  };

  function mergeDefaults(target, source) {
    if (!isObject(target) || !isObject(source)) return target;
    for (const [key, value] of Object.entries(source)) {
      if (target[key] === undefined || target[key] === null) target[key] = clone(value);
      else if (isObject(target[key]) && isObject(value)) mergeDefaults(target[key], value);
    }
    return target;
  }

  function createDefaultState() { return clone(defaultState); }

  const CLOTHING_SLOTS = new Set(['Head', 'Torso', 'Legs', 'Feet', 'Extra']);
  const CLOTHING_LAYERS = new Set(['Underwear', 'Base', 'Outerwear']);
  const CLOTHING_STAT_FIELDS = [
    'WeaponDamage', 'WeaponMagDamage', 'ArmorPDefBonus', 'ArmorMDefBonus',
    'StrBonus', 'AgiBonus', 'ConBonus', 'IntBonus', 'WisBonus', 'ChaBonus',
    'MaxHPBonus', 'MaxMPBonus', 'Effects', 'SpecialAbility', 'EquipmentLevel', 'Rarity', 'Qty',
  ];

  function normalizeClothingItem(key, value) {
    const item = isObject(value) ? value : {};
    const originalSlot = text(item.Slot).trim();
    item.Name = text(item.Name).trim() || key;
    item.Type = 'Clothing';
    item.Slot = CLOTHING_SLOTS.has(originalSlot) ? originalSlot : 'Extra';
    item.Layer = CLOTHING_LAYERS.has(text(item.Layer).trim()) ? text(item.Layer).trim() : 'Base';
    if (item.Slot === 'Extra' && !text(item.Placement).trim()) item.Placement = originalSlot || key;
    for (const field of ['Color', 'Material', 'Appearance', 'Condition', 'Arrangement']) {
      if (item[field] === undefined || item[field] === null) item[field] = '';
      else item[field] = text(item[field]);
    }
    for (const field of CLOTHING_STAT_FIELDS) delete item[field];
    return item;
  }

  function isClothingTombstone(key, value) {
    if (!isObject(value) || Object.keys(value).length === 0) return true;
    const allowed = new Set([
      'Name', 'Type', 'Slot', 'Layer', 'Placement',
      'Color', 'Material', 'Appearance', 'Condition', 'Arrangement',
    ]);
    if (Object.keys(value).some(field => !allowed.has(field))) return false;
    return text(value.Name).trim() === key &&
      lower(value.Type) === 'clothing' &&
      text(value.Slot).trim() === 'Extra' &&
      text(value.Layer).trim() === 'Base' &&
      text(value.Placement).trim() === key &&
      ['Color', 'Material', 'Appearance', 'Condition', 'Arrangement']
        .every(field => !text(value[field]).trim());
  }

  function normalizeOutfit(owner) {
    if (!isObject(owner)) return;
    if (!isObject(owner.Outfit)) owner.Outfit = { Initialized: false, Worn: {}, Wardrobe: {} };
    const outfit = owner.Outfit;
    outfit.Initialized = Boolean(outfit.Initialized);
    outfit.Worn = asRecord(outfit.Worn);
    outfit.Wardrobe = asRecord(outfit.Wardrobe);
    for (const bucket of ['Worn', 'Wardrobe']) {
      const opposite = bucket === 'Worn' ? outfit.Wardrobe : outfit.Worn;
      for (const [key, item] of Object.entries(outfit[bucket])) {
        const identityKey = text(item?.Name).trim() || key;
        const realTwin = [opposite[key], opposite[identityKey], outfit[bucket][identityKey]]
          .find(candidate => candidate !== item && isObject(candidate) && !isClothingTombstone(identityKey, candidate));
        // Legacy merge writers can leave {} behind after deleting an outfit
        // entry. Never inflate that tombstone into a synthetic garment. Also
        // remove already-inflated tombstones when the real item exists in
        // either bucket (including a duplicate key such as "Плащ_2").
        if (isClothingTombstone(identityKey, item) &&
            (!isObject(item) || Object.keys(item).length === 0 ||
             Boolean(realTwin))) {
          delete outfit[bucket][key];
          continue;
        }
        outfit[bucket][key] = normalizeClothingItem(key, item);
      }
    }
  }

  function migrateProjectionPaths(state) {
    if (!isObject(state)) return state;
    const narrative = asRecord(state.Narrative);
    const npcs = asRecord(narrative.NPCs);
    for (const bucket of ['Hot', 'Warm']) {
      for (const [id, npc] of Object.entries(asRecord(npcs[bucket]))) {
        if (/^npc_\d{4,}$/.test(id) && !npcs[id]) npcs[id] = npc;
      }
      delete npcs[bucket];
    }
    delete npcs.ColdCount;

    const familiar = asRecord(state.Familiar);
    for (const [id, member] of Object.entries(asRecord(familiar.Hot))) {
      if (!familiar[id]) familiar[id] = member;
    }
    delete familiar.Hot;
    delete familiar.ColdCount;

    const gmNotes = asRecord(narrative.GM_Notes);
    gmNotes.Active ||= {};
    for (const [id, note] of Object.entries(asRecord(gmNotes.Candidates))) {
      if (!gmNotes.Active[id]) gmNotes.Active[id] = note;
    }
    delete gmNotes.Candidates;
    delete gmNotes.ActiveCount;

    const chekhov = asRecord(narrative.Chekhov);
    chekhov.Active ||= {};
    for (const [id, seed] of Object.entries(asRecord(chekhov.Candidates))) {
      if (!chekhov.Active[id]) chekhov.Active[id] = seed;
    }
    delete chekhov.Candidates;
    delete chekhov.ActiveCount;
    delete chekhov.ArchiveCount;
    delete chekhov.AuditDue;

    const worldSim = asRecord(narrative.WorldSim);
    delete worldSim.ColdCount;
    delete state.ColdIndex;
    delete state.ProjectionMeta;
    return state;
  }

  const resolvedStatuses = new Set([
    'resolved', 'closed', 'paid', 'paid off', 'paid_off', 'invalid', 'expired',
    'cancelled', 'canceled', 'complete', 'completed', 'fulfilled', 'dead',
  ]);

  function recordTurn(record) {
    if (!isObject(record)) return 0;
    return Number(record.ResolvedTurn ?? record.LastTouchedTurn ?? record.LastShiftTurn ?? record.Turn ?? 0) || 0;
  }

  function trimRecord(record, limit) {
    const entries = Object.entries(asRecord(record));
    entries.sort((a, b) => recordTurn(b[1]) - recordTurn(a[1]));
    return Object.fromEntries(entries.slice(0, limit));
  }

  function compactArchive(id, record, turn) {
    const source = asRecord(record);
    return {
      ID: source.ID || id,
      Status: source.Status || 'resolved',
      Summary: source.Outcome || source.Summary || source.Payoff || source.Setup || source.Subject || source.Title || '',
      ResolvedTurn: Number(source.ResolvedTurn ?? turn) || turn,
      LastTouchedTurn: Number(source.LastTouchedTurn ?? turn) || turn,
    };
  }

  function archiveResolved(active, archive, turn, prefix) {
    const nextArchive = asRecord(archive);
    for (const [id, value] of Object.entries(asRecord(active))) {
      if (!isObject(value)) continue;
      if (!resolvedStatuses.has(lower(value.Status))) continue;
      const archiveId = prefix ? prefix + id : id;
      nextArchive[archiveId] = compactArchive(id, value, turn);
      delete active[id];
    }
    return nextArchive;
  }

  function inferRelationshipRefs(key, relation) {
    if (!isObject(relation)) return relation;
    const existingA = text(relation.A).trim();
    const existingB = text(relation.B).trim();
    if (existingA && existingB) return relation;

    const normalizedKey = text(key).trim();
    let inferredA = existingA;
    let inferredB = existingB;
    const playerWords = '(?:player|user|pc|mainchar)';

    let match = normalizedKey.match(new RegExp('^' + playerWords + '_(npc_\\d{4,})$', 'i'));
    if (match) {
      inferredA ||= 'player';
      inferredB ||= match[1];
    }

    match ||= normalizedKey.match(new RegExp('^(npc_\\d{4,})_' + playerWords + '$', 'i'));
    if (match && !inferredB) {
      inferredA ||= match[1];
      inferredB ||= 'player';
    }

    if (!inferredA || !inferredB) {
      const pair = normalizedKey.match(/^(npc_\d{4,})_(npc_\d{4,})$/i);
      if (pair) {
        inferredA ||= pair[1];
        inferredB ||= pair[2];
      }
    }

    if (inferredA) relation.A = lower(inferredA) === 'user' || lower(inferredA) === 'pc' || lower(inferredA) === 'mainchar' ? 'player' : inferredA;
    if (inferredB) relation.B = lower(inferredB) === 'user' || lower(inferredB) === 'pc' || lower(inferredB) === 'mainchar' ? 'player' : inferredB;
    return relation;
  }

  function actorAliasMap(state) {
    const aliases = new Map();
    const add = (alias, canonical) => {
      const key = lower(tupleValue(alias));
      if (key && !aliases.has(key)) aliases.set(key, canonical);
    };

    for (const alias of ['player', 'user', '{{user}}', 'pc', 'mainchar']) add(alias, 'player');
    add(state?.Mainchar?.Name, 'player');

    for (const [id, npc] of Object.entries(asRecord(state?.Narrative?.NPCs))) {
      add(id, id);
      add(npc?.ID, id);
      add(npc?.DisplayName, id);
      add(npc?.Name, id);
      for (const alias of asArray(npc?.Aliases)) add(alias, id);
    }

    for (const [id, member] of Object.entries(asRecord(state?.Familiar))) {
      add(id, id);
      add(member?.ID, id);
      add(member?.Name, id);
      add(member?.DisplayName, id);
      for (const alias of asArray(member?.Aliases)) add(alias, id);
    }
    return aliases;
  }

  function canonicalActorRef(value, aliases) {
    const raw = text(value).trim();
    return aliases.get(lower(raw)) || raw;
  }

  function normalizeState(input) {
    const state = isObject(input) ? clone(input) : createDefaultState();
    migrateProjectionPaths(state);
    mergeDefaults(state, defaultState);
    const narrative = state.Narrative;
    normalizeOutfit(state.Mainchar);
    for (const member of Object.values(asRecord(state.Familiar))) normalizeOutfit(member);
    const turn = Math.max(0, Math.trunc(Number(narrative.Turn) || 0));
    narrative.Turn = turn;
    narrative.NextNpcId = Math.max(1, Math.trunc(Number(narrative.NextNpcId) || 1));
    narrative.Scene.OpenLoops = unique(narrative.Scene.OpenLoops).slice(-12);
    narrative.Scene.PresentNPCs = unique(narrative.Scene.PresentNPCs).slice(0, 24);
    narrative.Scene.RelevantWorldKeys = unique(narrative.Scene.RelevantWorldKeys).slice(0, 24);

    let highestNpcId = 0;
    for (const [id, npcRaw] of Object.entries(asRecord(narrative.NPCs))) {
      if (!isObject(npcRaw)) continue;
      const numericId = /^npc_\d{4,}$/.test(id) ? Number(id.slice(4)) : 0;
      if (Number.isFinite(numericId)) highestNpcId = Math.max(highestNpcId, numericId);
      npcRaw.ID = id;
      npcRaw.Aliases = unique(npcRaw.Aliases).slice(0, 8);
      if (!text(npcRaw.DisplayName).trim()) {
        const fallbackName = text(npcRaw.Name).trim() || text(npcRaw.Aliases?.[0]).trim();
        if (fallbackName) npcRaw.DisplayName = fallbackName;
      }
      if (Array.isArray(npcRaw.CurrentThought)) npcRaw.CurrentThought = npcRaw.CurrentThought.at(-1) || '';
      if (Array.isArray(npcRaw.Knowledge)) npcRaw.Knowledge = npcRaw.Knowledge.slice(-20);
      else if (isObject(npcRaw.Knowledge)) npcRaw.Knowledge = trimRecord(npcRaw.Knowledge, 20);
      if (isObject(npcRaw.Agenda)) {
        delete npcRaw.Agenda.History;
        delete npcRaw.Agenda.Log;
        delete npcRaw.Agenda.Diary;
        delete npcRaw.Agenda.Past;
      }
    }
    narrative.NextNpcId = Math.max(narrative.NextNpcId, highestNpcId + 1);

    const actorAliases = actorAliasMap(state);
    narrative.Scene.PresentNPCs = unique(narrative.Scene.PresentNPCs.map(value => canonicalActorRef(value, actorAliases))).slice(0, 24);

    for (const [relationId, relation] of Object.entries(asRecord(narrative.Relationships))) {
      if (!isObject(relation)) continue;
      inferRelationshipRefs(relationId, relation);
      relation.A = canonicalActorRef(relation.A, actorAliases);
      relation.B = canonicalActorRef(relation.B, actorAliases);
      relation.Bond = clamp(relation.Bond, -100, 100);
      relation.Sparks = clamp(relation.Sparks, 0, 100);
      relation.Grudge = clamp(relation.Grudge, 0, 100);
      delete relation.History;
      delete relation.Log;
    }

    narrative.GM_Notes.Archive = archiveResolved(narrative.GM_Notes.Active, narrative.GM_Notes.Archive, turn, '');
    narrative.GM_Notes.Archive = trimRecord(narrative.GM_Notes.Archive, 30);
    narrative.Chekhov.Archive = archiveResolved(narrative.Chekhov.Active, narrative.Chekhov.Archive, turn, '');
    narrative.Chekhov.Archive = trimRecord(narrative.Chekhov.Archive, 50);
    narrative.Chekhov.AuditEvery = Math.max(4, Math.min(30, Math.trunc(Number(narrative.Chekhov.AuditEvery) || 8)));
    narrative.Chekhov.LastAuditTurn = Math.max(0, Math.trunc(Number(narrative.Chekhov.LastAuditTurn) || 0));
    const worldArchive = asRecord(narrative.WorldSim.Archive);
    narrative.WorldSim.Archive = archiveResolved(narrative.WorldSim.Threads, worldArchive, turn, 'thread:');
    narrative.WorldSim.Archive = archiveResolved(narrative.WorldSim.Pressures, narrative.WorldSim.Archive, turn, 'pressure:');
    narrative.WorldSim.Archive = trimRecord(narrative.WorldSim.Archive, 30);
    state.MVUStatMenu_DB_Ver = VERSION;
    state.GameStarted = Boolean(state.GameStarted);
    return state;
  }


  function validateState(state) {
    const errors = [];
    if (!isObject(state)) return ['stat_data is not an object'];
    const world = state.World || {};
    for (const key of ['Date', 'Time', 'Location', 'Weather']) {
      if (!Array.isArray(world[key]) || world[key].length < 2) errors.push('World.' + key + ' is not a labeled tuple');
    }
    const mc = state.Mainchar || {};
    for (const key of ['Name', 'Age', 'Gender', 'Race', 'Occupation', 'Level', 'Strength', 'Agility', 'Constitution', 'Intelligence', 'Wisdom', 'Charisma']) {
      if (!Array.isArray(mc[key]) || mc[key].length < 2) errors.push('Mainchar.' + key + ' is not a labeled tuple');
    }
    const narrative = state.Narrative;
    if (!isObject(narrative)) return errors.concat('Narrative is missing');
    const ids = Object.keys(asRecord(narrative.NPCs));
    const familiarIds = new Set(Object.keys(asRecord(state.Familiar)));
    let highest = 0;
    for (const id of ids) {
      if (!/^npc_\d{4,}$/.test(id)) errors.push('Invalid NPC ID: ' + id);
      const number = Number(id.slice(4));
      if (Number.isFinite(number)) highest = Math.max(highest, number);
      if (narrative.NPCs[id]?.ID !== id) errors.push('NPC ID mismatch: ' + id);
    }
    if (!Number.isInteger(narrative.NextNpcId) || narrative.NextNpcId <= highest) errors.push('NextNpcId was not advanced atomically');
    for (const id of asArray(narrative.Scene?.PresentNPCs)) {
      if (!narrative.NPCs[id] && !familiarIds.has(id)) errors.push('PresentNPCs references a missing actor: ' + id);
    }
    for (const [id, relation] of Object.entries(asRecord(narrative.Relationships))) {
      if (!isObject(relation)) { errors.push('Relationship is not an object: ' + id); continue; }
      for (const side of ['A', 'B']) {
        const ref = text(relation[side]);
        // Relationship endpoints may be stable NPC IDs, familiar keys, the player,
        // or free-form actors not promoted to the persistent NPC registry yet.
        // Known aliases are canonicalized by normalizeState; an unknown endpoint
        // must not invalidate and roll back an otherwise valid turn.
        if (!ref) errors.push('Relationship ' + id + ' has an empty ' + side);
      }
    }
    return [...new Set(errors)];
  }

  function priority(record) {
    const raw = record?.Priority;
    if (typeof raw === 'number') return raw;
    const value = lower(raw);
    if (value === 'critical') return 5;
    if (value === 'high' || value === 'hot') return 4;
    if (value === 'medium' || value === 'warm') return 2;
    if (value === 'low' || value === 'cold') return 1;
    return 0;
  }

  function intersects(left, right) {
    const target = new Set(asArray(right).map(text));
    return asArray(left).some(value => target.has(text(value)));
  }

  function candidateScore(record, context) {
    if (!isObject(record)) return -1;
    let score = priority(record);
    const actors = asArray(record.Actors || record.NPCs || record.Participants);
    const locations = asArray(record.Locations || record.LocationKeys || (record.Location ? [record.Location] : []));
    if (intersects(actors, context.actorIds)) score += 4;
    if (locations.some(value => lower(value) === context.location)) score += 4;
    const earliest = Number(record.EarliestTurn ?? record.DeadlineTurn ?? 0) || 0;
    if (earliest && earliest <= context.turn) score += 3;
    if (['ready', 'active', 'triggered', 'urgent', 'hot'].includes(lower(record.Status))) score += 2;

    // Narrative threads often use semantic continuation fields instead of routing metadata.
    // Treat an explicit unresolved next step as a warm signal so a live thread cannot
    // disappear from MODEL_STATE merely because the model omitted Priority/Actors/Status.
    const nextPressure = text(record.next_pressure ?? record.NextPressure ?? record.NextAction ?? record.NextBeat).trim();
    if (nextPressure) score += 2;

    const touched = recordTurn(record);
    if (touched > 0 && context.turn >= touched && context.turn - touched <= 4) score += 1;
    return score;
  }

  function pickCandidates(record, context, limit, minimum) {
    return Object.fromEntries(
      Object.entries(asRecord(record))
        .map(([id, value]) => [id, value, candidateScore(value, context)])
        .filter(item => item[2] >= minimum)
        .sort((a, b) => b[2] - a[2] || recordTurn(b[1]) - recordTurn(a[1]))
        .slice(0, limit)
        .map(([id, value]) => [id, clone(value)]),
    );
  }

  function compactNpcIndex(record, limit) {
    return Object.values(asRecord(record)).slice(0, limit).map(npc => ({
      ID: npc.ID || '', DisplayName: npc.DisplayName || npc.Name || '',
      Location: npc.Location || '', Status: npc.Status || '',
    }));
  }

  function pickWorldCalc(state, relevantKeys) {
    const source = asRecord(state.World_Calc);
    const result = { Factions: {}, Locations: {}, Ruins: {}, Events: {} };
    const keys = new Set(asArray(relevantKeys).map(lower));
    const currentLocation = lower(tupleValue(state.World?.Location));
    for (const section of Object.keys(result)) {
      const entries = Object.entries(asRecord(source[section]));
      const selected = entries.filter(([key, value]) => {
        if (keys.has(lower(key))) return true;
        if (section === 'Locations' && currentLocation && (lower(key) === currentLocation || currentLocation.includes(lower(key)))) return true;
        return ['active', 'urgent', 'hot'].includes(lower(value?.Status));
      });
      const fallback = entries.length <= 6 ? entries : [];
      result[section] = Object.fromEntries((selected.length ? selected : fallback).slice(0, 8).map(([key, value]) => [key, clone(value)]));
    }
    return result;
  }

  function buildPromptView(input, options = {}) {
    const state = normalizeState(input);
    const narrative = state.Narrative;
    const scene = narrative.Scene;
    const turn = narrative.Turn;
    const location = lower(scene.LocationKey || tupleValue(state.World.Location));
    const explicitHot = new Set(asArray(scene.PresentNPCs));
    for (const [id, npc] of Object.entries(asRecord(narrative.NPCs))) {
      if (npc.IsPresent === true || lower(npc.Temperature) === 'hot') explicitHot.add(id);
    }
    const familiarHot = {};
    const familiarCold = [];
    for (const [id, member] of Object.entries(asRecord(state.Familiar))) {
      if (tupleValue(member.Is_present) === true || tupleValue(member.Is_in_battle_team) === true || explicitHot.has(id)) familiarHot[id] = clone(member);
