    for (let id = 0; id <= targetMessageId; id += 1) {
      const variables = readVariables(id);
      const state = validPreparedState(variables?.stat_data);
      if (!state || state.GameStarted !== true) continue;
      const patch = isUserMessage(id) ? null : safeExtractJsonPatch(id);
      if (patch?.error || patch) continue;
      return { state, messageId: id, patchHash: '' };
    }
    return null;
  }

  function recoverMissingNpcIdentityFromHistory(state, targetMessageId) {
    const narrative = state?.Narrative;
    if (!isObject(narrative)) return state;
    const missing = new Set(Object.entries(asRecord(narrative.NPCs))
      .filter(([, npc]) => isObject(npc) && !text(npc.DisplayName).trim() && !text(npc.Name).trim() && !asArray(npc.Aliases).length)
      .map(([id]) => id));
    if (!missing.size) return state;

    const found = {};
    for (let id = 0; id <= targetMessageId && missing.size; id += 1) {
      if (isUserMessage(id)) continue;
      const patch = safeExtractJsonPatch(id);
      if (!patch || patch.error) continue;
      for (const operation of patch.operations) {
        const path = text(operation?.path);
        const exact = path.match(/^\/Narrative\/NPCs\/(npc_\d{4,})$/);
        const leaf = path.match(/^\/Narrative\/NPCs\/(npc_\d{4,})\/(DisplayName|Name|Aliases)$/);
        const npcId = exact?.[1] || leaf?.[1];
        if (!npcId || !missing.has(npcId)) continue;
        found[npcId] ||= {};
        if (exact && isObject(operation.value)) {
          if (text(operation.value.DisplayName).trim()) found[npcId].DisplayName = operation.value.DisplayName;
          if (text(operation.value.Name).trim()) found[npcId].Name = operation.value.Name;
          if (asArray(operation.value.Aliases).length) found[npcId].Aliases = operation.value.Aliases;
        } else if (leaf) {
          found[npcId][leaf[2]] = clone(operation.value);
        }
      }
    }

    for (const npcId of missing) {
      const npc = narrative.NPCs[npcId];
      const old = found[npcId];
      if (!old) continue;
      if (!text(npc.DisplayName).trim() && text(old.DisplayName).trim()) npc.DisplayName = old.DisplayName;
      if (!text(npc.Name).trim() && text(old.Name).trim()) npc.Name = old.Name;
      if (!asArray(npc.Aliases).length && asArray(old.Aliases).length) npc.Aliases = unique(old.Aliases).slice(0, 8);
    }
    return state;
  }

  function replayStateTo(targetMessageId) {
    const trusted = findTrustedBase(targetMessageId);
    const base = trusted || findGameStartBase(targetMessageId) || { state: createDefaultState(), messageId: -1, patchHash: '' };
    let state = clone(base.state);
    let sourceMessageId = base.messageId;
    let lastPatchHash = base.patchHash || '';
    for (let id = base.messageId + 1; id <= targetMessageId; id += 1) {
      if (isUserMessage(id)) continue;
      const patch = safeExtractJsonPatch(id);
      if (patch?.error) throw new Error('Message #' + id + ': ' + patch.error.message);
      if (!patch) continue;
      state = normalizeState(applyJsonPatch(state, patch.operations));
      const errors = validateState(state);
      if (errors.length) throw new Error('Message #' + id + ': ' + errors.join('; '));
      sourceMessageId = id;
      lastPatchHash = patch.hash;
    }
    state = normalizeState(recoverMissingNpcIdentityFromHistory(state, targetMessageId));
    return { state, sourceMessageId, lastPatchHash, baseMessageId: base.messageId };
  }

  function cachedPromptView(messageId, state) {
    if (messageId < 0) return null;
    const variables = readVariables(messageId);
    const view = variables?.ff_mvu_prompt_view;
    const meta = asRecord(variables?.[SNAPSHOT_META_KEY]);
    if (!isObject(view)) return null;
    if (meta.Version !== VERSION || meta.MessageId !== messageId || meta.Branch !== branchToken(messageId)) return null;
    if (text(meta.StateHash) !== patchHash(stableStringify(state))) return null;
    if (text(meta.ProjectionHash) !== patchHash(stableStringify(view))) return null;
    return clone(view);
  }

  function getPromptSnapshot(messageId = latestMessageId()) {
    if (messageId < 0) throw new Error('No active message for MODEL_STATE');
    const replay = replayStateTo(messageId);
    const state = normalizeState(replay.state);
    const zodResult = StatDataSchema.safeParse(state);
    const errors = validateState(state);
    if (!zodResult.success) errors.push('Schema validation failed');
    if (errors.length) throw new Error(errors.join('; '));
    let view = cachedPromptView(replay.sourceMessageId, state);
    if (!view) view = buildPromptView(state, { consumeAudit: false }).view;
    return {
      state,
      view,
      targetMessageId: messageId,
      sourceMessageId: replay.sourceMessageId,
      stateHash: patchHash(stableStringify(state)),
    };
  }

  function replaceLiveModelState(source, serialized) {
    if (typeof source !== 'string') return { value: source, changed: false };
    if (source.includes(LIVE_STATE_SENTINEL)) {
      return { value: source.replace(LIVE_STATE_SENTINEL, serialized), changed: true };
    }
    if (MODEL_STATE_RE.test(source)) {
      return { value: source.replace(MODEL_STATE_RE, '<MODEL_STATE>\n' + serialized + '\n</MODEL_STATE>'), changed: true };
    }
    return { value: source, changed: false };
  }

  function injectPromptMessages(messages) {
    if (!Array.isArray(messages)) return false;
    const snapshot = getPromptSnapshot();
    const serialized = JSON.stringify(snapshot.view);
    for (const message of messages) {
      const result = replaceLiveModelState(message?.content, serialized);
      if (!result.changed) continue;
      message.content = result.value;
      console.info('[FFMVU] Live MODEL_STATE injected', {
        targetMessageId: snapshot.targetMessageId,
        sourceMessageId: snapshot.sourceMessageId,
        turn: snapshot.view?.Narrative?.Turn,
        time: snapshot.view?.World?.Time?.[0],
        stateHash: snapshot.stateHash,
      });
      return true;
    }
    console.warn('[FFMVU] No MODEL_STATE block found in outgoing prompt.');
    return false;
  }

  function injectPromptString(source) {
    const snapshot = getPromptSnapshot();
    const result = replaceLiveModelState(source, JSON.stringify(snapshot.view));
    if (!result.changed) console.warn('[FFMVU] No MODEL_STATE block found in outgoing text prompt.');
    return result.value;
  }

  async function previousSnapshot(messageId) {
    if (messageId <= 0) return null;
    const replay = replayStateTo(messageId - 1);
    return { state: replay.state, messageId: replay.sourceMessageId };
  }

  async function selectSource(messageId) {
    const replay = replayStateTo(messageId);
    return {
      state: replay.state,
      messageId: replay.sourceMessageId,
      kind: isUserMessage(messageId) ? 'inherited' : (safeExtractJsonPatch(messageId) ? 'committed-patch' : 'committed-no-patch'),
    };
  }

  async function ensureMessageState(messageId) {
    if (disposed || messageId < 0 || !getMvu()) return;
    const replay = replayStateTo(messageId);
    const targetPatch = isUserMessage(messageId) ? null : safeExtractJsonPatch(messageId);
    if (targetPatch?.error) throw targetPatch.error;
    const prepared = buildPromptView(replay.state, { consumeAudit: true });
    const zodResult = StatDataSchema.safeParse(prepared.state);
    const errors = validateState(prepared.state);
    if (!zodResult.success) errors.push('Schema validation failed');
    if (errors.length) throw new Error(errors.join('; '));
    const existing = readVariables(messageId) || {};
    existing.stat_data = prepared.state;
    existing.ff_mvu_prompt_view = prepared.view;
    let kind = 'inherited';
    if (!isUserMessage(messageId)) {
      if (targetPatch) kind = 'committed-patch';
      else if (prepared.state.GameStarted === true && messageId === replay.baseMessageId) kind = 'gamestart';
      else kind = 'committed-no-patch';
    }
    stampSnapshot(existing, messageId, kind, replay.sourceMessageId, targetPatch?.hash || '');
    const beforeHash = JSON.stringify(readVariables(messageId) || {});
    const afterHash = JSON.stringify(existing);
    if (beforeHash === afterHash) return;
    writingMessageIds.add(messageId);
    try { await writeVariables(messageId, existing); }
    finally { writingMessageIds.delete(messageId); }
  }

  async function commitExternalState(messageId, inputState, kind = 'external-edit') {
    if (disposed || !Number.isInteger(messageId) || messageId < 0) throw new Error('Invalid external state target');
    const prepared = buildPromptView(inputState, { consumeAudit: false });
    const zodResult = StatDataSchema.safeParse(prepared.state);
    const errors = validateState(prepared.state);
    if (!zodResult.success) errors.push('Schema validation failed');
    if (errors.length) throw new Error(errors.join('; '));
    const variables = readVariables(messageId) || {};
    variables.stat_data = prepared.state;
    variables.ff_mvu_prompt_view = prepared.view;
    const patch = isUserMessage(messageId) ? null : safeExtractJsonPatch(messageId);
    if (patch?.error) throw patch.error;
    stampSnapshot(variables, messageId, kind, messageId, patch?.hash || '');
    writingMessageIds.add(messageId);
    try { await writeVariables(messageId, variables); }
    finally { writingMessageIds.delete(messageId); }
    return clone(prepared.state);
  }

  // Compatibility safety net for old GUI / StatusMenu / GameStart versions that still write stat_data directly.
  async function reconcileExternalWrite(messageId = latestMessageId()) {
    if (disposed || messageId < 0 || writingMessageIds.has(messageId)) return;
    const variables = readVariables(messageId) || {};
    if (!isObject(variables.stat_data)) {
      await ensureMessageState(messageId);
      return;
    }

    const targetPatch = isUserMessage(messageId) ? null : safeExtractJsonPatch(messageId);
    if (targetPatch?.error) throw targetPatch.error;
    const expected = normalizeState(replayStateTo(messageId).state);
    const current = repairLabeledTuples(normalizeState(variables.stat_data), expected);
    const zodResult = StatDataSchema.safeParse(current);
    const currentErrors = validateState(current);
    if (!zodResult.success) currentErrors.push('Schema validation failed');
    if (currentErrors.length) {
      console.error('[FFMVU] Rejected invalid external stat_data:', currentErrors.join('; '));
      await ensureMessageState(messageId);
      return;
    }

    // replayStateTo ignores this message's mutated snapshot unless its meta/hash is still trusted.
    const currentHash = patchHash(stableStringify(current));
    const expectedHash = patchHash(stableStringify(expected));
    const meta = asRecord(variables[SNAPSHOT_META_KEY]);
    const projectionHash = patchHash(stableStringify(variables.ff_mvu_prompt_view || {}));

    // A visible assistant patch is the authoritative transaction for this
    // message. If the external writer has not applied it yet, commit replayed
    // state instead of misclassifying the older state as a newer external edit.
    if (targetPatch && currentHash !== expectedHash) {
      await ensureMessageState(messageId);
      return;
    }

    const alreadyTrusted =
      meta.Version === VERSION &&
      meta.MessageId === messageId &&
      meta.Branch === branchToken(messageId) &&
      text(meta.StateHash) === currentHash &&
      text(meta.ProjectionHash) === projectionHash;
    if (alreadyTrusted) return;

    if (currentHash !== expectedHash) {
      const kind = current.GameStarted === true && expected.GameStarted !== true ? 'gamestart' : 'external-edit';
      await commitExternalState(messageId, current, kind);
      console.info('[FFMVU] Adopted external state edit', { messageId, kind, stateHash: currentHash });
      return;
    }

    await ensureMessageState(messageId);
  }

  function enqueue(job) {
    ensureQueue = ensureQueue.then(async () => {
      if (disposed) return;
      await job();
      lastReconcileError = '';
    }).catch(error => {
      lastReconcileError = error?.message || String(error);
      console.error('[FFMVU] State reconciliation failed:', error);
    });
    return ensureQueue;
  }

  function enqueueEnsure(messageId) {
    return enqueue(async () => {
      if (messageId < 0) return;
      await ensureMessageState(messageId);
    });
  }

  function ensureLatestState() {
    return enqueue(async () => {
      const id = latestMessageId();
      if (id >= 0) await reconcileExternalWrite(id);
    });
  }

  function scheduleLatest(delays = [80, 350, 900, 1800]) {
    for (const delay of delays) {
      const timer = setTimeout(() => {
        timers.delete(timer);
        void ensureLatestState();
      }, delay);
      timers.add(timer);
    }
  }

  function onVariableUpdateEnded() {
    const id = latestMessageId();
    if (disposed || id < 0 || writingMessageIds.has(id)) return;
    void enqueue(() => reconcileExternalWrite(id));
  }

  function subscribe(eventName, handler) {
    if (!eventName) return;
    const on = runtimeFunction('eventOn');
    if (!on) return;
    on(eventName, handler);
    subscriptions.push(() => {
      try {
        const remove = runtimeFunction('eventRemoveListener');
        remove?.(eventName, handler);
      } catch (error) {}
    });
  }

  async function initialize() {
    const waitGlobalInitializedFn = runtimeFunction('waitGlobalInitialized');
    if (waitGlobalInitializedFn) {
      try { await waitGlobalInitializedFn('Mvu'); } catch (error) {}
    }
    const mvu = getMvu();
    if (!mvu?.events) { setTimeout(initialize, 1000); return; }
    registerMvuSchema(StatDataSchema);
    subscribe(mvu.events.VARIABLE_UPDATE_ENDED, onVariableUpdateEnded);
    const events = getTavernEvents();

    const beforeGeneration = async () => {
      const id = latestMessageId();
      if (id >= 0) await enqueue(() => reconcileExternalWrite(id));
    };
    for (const name of ['GENERATION_STARTED', 'GENERATION_AFTER_COMMANDS']) {
      if (events[name]) subscribe(events[name], beforeGeneration);
    }

    if (events.MESSAGE_SENT) {
      subscribe(events.MESSAGE_SENT, async messageId => {
        const parsed = Number(messageId);
        const targetId = Number.isFinite(parsed) && parsed >= 0 ? parsed : latestMessageId();
        await enqueueEnsure(targetId);
        scheduleLatest([120, 450]);
      });
    }

    if (events.CHAT_COMPLETION_PROMPT_READY) {
      subscribe(events.CHAT_COMPLETION_PROMPT_READY, eventData => {
        try { injectPromptMessages(eventData?.chat); }
        catch (error) {
          lastReconcileError = error?.message || String(error);
          console.error('[FFMVU] Late MODEL_STATE injection failed:', error);
        }
      });
    }

    if (events.GENERATE_AFTER_DATA) {
      subscribe(events.GENERATE_AFTER_DATA, generateData => {
        try {
          if (Array.isArray(generateData?.prompt)) injectPromptMessages(generateData.prompt);
          else if (typeof generateData?.prompt === 'string') generateData.prompt = injectPromptString(generateData.prompt);
        } catch (error) {
          lastReconcileError = error?.message || String(error);
          console.error('[FFMVU] GENERATE_AFTER_DATA injection failed:', error);
        }
      });
    }

    const names = ['CHAT_CHANGED', 'MESSAGE_SWIPED', 'MESSAGE_DELETED', 'MESSAGE_EDITED', 'MESSAGE_UPDATED', 'MESSAGE_RECEIVED'];
    [...new Set(names.map(name => events[name]).filter(Boolean))].forEach(eventName => subscribe(eventName, () => scheduleLatest()));
    const initialId = latestMessageId();
    if (initialId >= 0) await enqueue(() => reconcileExternalWrite(initialId));
    console.log('[FFMVU] Core ' + VERSION + ' ready.');
  }

  function getRuntimeDiagnostics() {
    const st = getSillyTavern();
    return {
      version: VERSION,
      latestMessageId: latestMessageId(),
      currentChatId: currentChatId(),
      chatLength: Array.isArray(st?.chat) ? st.chat.length : null,
      scriptWindow: {
        getLastMessageId: typeof scriptWindow?.getLastMessageId === 'function',
        eventOn: typeof scriptWindow?.eventOn === 'function',
        tavern_events: Boolean(scriptWindow?.tavern_events),
        SillyTavern: Boolean(scriptWindow?.SillyTavern),
        Mvu: Boolean(scriptWindow?.Mvu),
      },
      host: {
        getLastMessageId: typeof host?.getLastMessageId === 'function',
        eventOn: typeof host?.eventOn === 'function',
        tavern_events: Boolean(host?.tavern_events),
        SillyTavern: Boolean(host?.SillyTavern),
        Mvu: Boolean(host?.Mvu),
      },
    };
  }

  function cleanup() {
    if (disposed) return;
    disposed = true;
    for (const timer of timers) clearTimeout(timer);
    timers.clear();
    while (subscriptions.length) subscriptions.pop()();
    if (host.FFMVU?.cleanup === cleanup) delete host.FFMVU;
    if (scriptWindow.FFMVU?.cleanup === cleanup) delete scriptWindow.FFMVU;
  }

  if (typeof host.FFMVU?.cleanup === 'function') {
    try { host.FFMVU.cleanup(); } catch (error) {}
  }

  const publicApi = {
    VERSION, StatDataSchema, createDefaultState, normalizeState, validateState,
    buildPromptView: state => buildPromptView(state, { consumeAudit: false }).view,
    prepareState: state => buildPromptView(state, { consumeAudit: true }),
    canonicalizeTupleOperation, repairLabeledTuples, patchEffectsPresent,
    ensureLatestState, ensureMessageState, replayStateTo, previousSnapshot, selectSource, stampSnapshot,
    getPromptSnapshot, commitExternalState, reconcileExternalWrite,
    injectPromptMessages,
    extractJsonPatch, applyJsonPatch, readVariables, writeVariables, latestMessageId, branchToken,
    getRuntimeDiagnostics,
    getLastReconcileError: () => lastReconcileError, cleanup,
  };

  host.FFMVU = publicApi;
  scriptWindow.FFMVU = publicApi;

  scriptWindow.addEventListener('pagehide', cleanup, { once: true });
  if (typeof $ === 'function') $(() => setTimeout(initialize, 0));
  else setTimeout(initialize, 0);
})();
